static std::array<double,6> affine(int which,double t) {return which==0 ? std::array<double,6>{7000+t,-100+2*t,200-.5*t,1,2,-.5} : std::array<double,6>{-1500-3*t,6000+.25*t,-300+1.5*t,-3,.25,1.5};}
static void spiceCheck() {if (failed_c()) {char text[1841];getmsg_c("LONG",sizeof(text),text);reset_c();throw std::runtime_error(text);}}
static void fixture(const QString &path)
{
   SpiceInt handle;spkopn_c(path.toUtf8().constData(),"Mixed group fixture",0,&handle);spiceCheck();SpiceDouble epochs[]={0,170,900},states[3][6];
   for (int body=0;body<2;++body) {for (int i=0;i<3;++i) {const auto value=affine(body,epochs[i]);for (int j=0;j<6;++j) states[i][j]=value[j];}spkw09_c(handle,-100078-body,399,"J2000",0,900,body==0 ? "GROUP A" : "GROUP B",1,3,states,epochs);spiceCheck();}spkcls_c(handle);spiceCheck();
}
